// Offline MCWorld reader. Opens only an extracted copy, never a game connection.
package main
import("bufio";"encoding/binary";"encoding/json";"fmt";"os";"sort";"strings";"github.com/df-mc/goleveldb/leveldb";"github.com/df-mc/goleveldb/leveldb/opt";"github.com/TriM-Organization/bedrock-world-operator/world";"github.com/TriM-Organization/bedrock-world-operator/define";"github.com/TriM-Organization/bedrock-world-operator/block";"github.com/TriM-Organization/bedrock-world-operator/chunk")
type state struct{Name string `json:"name"`;States map[string]any `json:"states"`}
func run()error{if len(os.Args)!=3{return fmt.Errorf("usage: extracted-world output-prefix")};dir,out:=os.Args[1],os.Args[2]
 db,e:=leveldb.OpenFile(dir+"/db",&opt.Options{ReadOnly:true});if e!=nil{return e};it:=db.NewIterator(nil,nil);positions:=map[[2]int32]bool{};for it.Next(){k:=it.Key();if (len(k)==9||len(k)==10)&&(k[8]==47||k[8]==44||k[8]==118){positions[[2]int32{int32(binary.LittleEndian.Uint32(k)),int32(binary.LittleEndian.Uint32(k[4:]))}]=true}};e=it.Error();it.Release();db.Close();if e!=nil{return e};if len(positions)==0{return fmt.Errorf("no overworld chunks")}
 // Retain every decoded state, including newer names absent from the pinned
 // static runtime palette. Runtime IDs are local to this offline process.
 palette:=[]state{{"minecraft:air",map[string]any{}}};keyIDs:=map[string]uint32{};ids:=map[uint32]int{block.AirRuntimeID:0};next:=uint32(1)
 block.StateToRuntimeID=func(name string,props map[string]any)(uint32,bool){if !strings.HasPrefix(name,"minecraft:"){name="minecraft:"+name};if name=="minecraft:air"{return block.AirRuntimeID,true};if name=="minecraft:unknown"||name=="minecraft:"{panic("unknown source block")};copyProps:=map[string]any{};for k,v:=range props{copyProps[k]=v};b,_:=json.Marshal(state{name,copyProps});key:=string(b);if id,ok:=keyIDs[key];ok{return id,true};for next==block.AirRuntimeID{next++};id:=next;next++;keyIDs[key]=id;ids[id]=len(palette);palette=append(palette,state{name,copyProps});return id,true}
 w,e:=(world.Config{LDBOptions:&opt.Options{ReadOnly:true}}).Open(dir,nil);if e!=nil{return e};defer w.Close()
 keys:=make([][2]int32,0,len(positions));for p:=range positions{keys=append(keys,p)};sort.Slice(keys,func(i,j int)bool{if keys[i][0]!=keys[j][0]{return keys[i][0]<keys[j][0]};return keys[i][1]<keys[j][1]})
 minx,minz,maxx,maxz:=keys[0][0],keys[0][1],keys[0][0],keys[0][1];miny,maxy:=999,-999;count,secondary:=int64(0),int64(0);nbts:=0;entities:=[]map[string]any{};chunks:=map[[2]int32]*chunk.Chunk{}
 for i,p:=range keys{if p[0]<minx{minx=p[0]};if p[0]>maxx{maxx=p[0]};if p[1]<minz{minz=p[1]};if p[1]>maxz{maxz=p[1]};c,ok,e:=w.LoadChunk(define.Dimension(0),define.ChunkPos{p[0],p[1]});if e!=nil{return e};if !ok{return fmt.Errorf("missing chunk %v",p)};chunks[p]=c;n,e:=w.LoadNBT(define.Dimension(0),define.ChunkPos{p[0],p[1]});if e!=nil{return e};nbts+=len(n);entities=append(entities,n...)
 for si,sub:=range c.Sub(){if sub==nil||sub.Empty(){continue};base:=int(c.SubY(int16(si)));for li,layer:=range sub.Layers(){for x:=byte(0);x<16;x++{for y:=byte(0);y<16;y++{for z:=byte(0);z<16;z++{id:=layer.At(x,y,z);if id==block.AirRuntimeID{continue};if _,ok:=ids[id];!ok{return fmt.Errorf("unregistered block %d",id)};if li>0{secondary++;continue};ay:=base+int(y);if ay<miny{miny=ay};if ay>maxy{maxy=ay};count++}}}}};if i%128==0{fmt.Fprintf(os.Stderr,"read %d/%d chunks\n",i+1,len(keys))}}
 sx,sy,sz:=int(maxx-minx+1)*16,maxy-miny+1,int(maxz-minz+1)*16;if sy<1||sy>384||int64(sx)*int64(sy)*int64(sz)>500000000{return fmt.Errorf("world dimensions exceed safe offline limit")}
 f,e:=os.Create(out+".bin");if e!=nil{return e};bw:=bufio.NewWriterSize(f,1024*1024);plane:=make([]byte,sy*sz*4)
 for x:=0;x<sx;x++{clear(plane);cx:=minx+int32(x/16);for z:=0;z<sz;z++{c:=chunks[[2]int32{cx,minz+int32(z/16)}];if c==nil{continue};for y:=0;y<sy;y++{id:=c.Block(byte(x%16),int16(y+miny),byte(z%16),0);index,ok:=ids[id];if !ok{return fmt.Errorf("unregistered block")};binary.LittleEndian.PutUint32(plane[(y*sz+z)*4:],uint32(index))}};if _,e=bw.Write(plane);e!=nil{f.Close();return e}};if e=bw.Flush();e!=nil{f.Close();return e};if e=f.Close();e!=nil{return e}
 for i:=range palette{for k,v:=range palette[i].States{switch x:=v.(type){case byte:palette[i].States[k]=x!=0;case int8:palette[i].States[k]=x!=0}}}
 meta:=map[string]any{"size":[]int{sx,sy,sz},"source_min":[]int{int(minx)*16,miny,int(minz)*16},"palette":palette,"blocks":count,"secondary_blocks":secondary,"block_entities":nbts,"block_entity_data":entities,"dimensions":"overworld"};b,e:=json.Marshal(meta);if e!=nil{return e};return os.WriteFile(out+".json",b,0600)
}
func main(){if e:=run();e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)}}
